मनन्तबाहुं शशिसूर्यनेत्रम् ।
पश्यामि त्वां दीप्‍तहुताशवक्‍त्रं
स्वतेजसा विश्वमिदं तपन्तम् ॥ १९ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":3235,\"bb\":2855,\"url_path\":\"/en/library/bg/11/19/b2855/\",\"body_value\":\"anādi-madhyāntam ananta-vīryam
ananta-bāhuṁ śaśi-sūrya-netram
paśyāmi tvāṁ dīpta-hutāśa-vaktraṁ
sva-tejasā viśvam idaṁ tapantam\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":3236,\"bb\":2856,\"url_path\":\"/en/library/bg/11/19/b2856/\",\"shadow_value\":\"anādi – without beginning; madhya – middle; antam – or end; ananta – unlimited; vīryam – glories; ananta – unlimited; bāhum – arms; śaśi – the moon; sūrya – and sun; netram – eyes; paśyāmi – I see; tvām – You; dīpta – blazing; hutāśa-vaktram – fire coming out of Your mouth; sva-tejasā – by Your radiance; viśvam – universe; idam – this; tapantam – heating.\",\"word_for_word_value\":[{\"word\":\"anādi\",\"translation\":\"without beginning\"},{\"word\":\"madhya\",\"translation\":\"middle\"},{\"word\":\"antam\",\"translation\":\"or end\"},{\"word\":\"ananta\",\"translation\":\"unlimited\"},{\"word\":\"vīryam\",\"translation\":\"glories\"},{\"word\":\"ananta\",\"translation\":\"unlimited\"},{\"word\":\"bāhum\",\"translation\":\"arms\"},{\"word\":\"śaśi\",\"translation\":\"the moon\"},{\"word\":\"sūrya\",\"translation\":\"and sun\"},{\"word\":\"netram\",\"translation\":\"eyes\"},{\"word\":\"paśyāmi\",\"translation\":\"I see\"},{\"word\":\"tvām\",\"translation\":\"You\"},{\"word\":\"dīpta\",\"translation\":\"blazing\"},{\"word\":\"hutāśa-vaktram\",\"translation\":\"fire coming out of Your mouth\"},{\"word\":\"sva-tejasā\",\"translation\":\"by Your radiance\"},{\"word\":\"viśvam\",\"translation\":\"universe\"},{\"word\":\"idam\",\"translation\":\"this\"},{\"word\":\"tapantam\",\"translation\":\"heating\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":3237,\"bb\":2857,\"url_path\":\"/en/library/bg/11/19/b2857/\",\"body_value\":\"You are without origin, middle or end. Your glory is unlimited. You have numberless arms, and the sun and moon are Your eyes. I see You with blazing fire coming forth from Your mouth, burning this entire universe by Your own radiance.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":3238,\"bb\":2858,\"url_path\":\"/en/library/bg/11/19/b2858/\",\"body_value\":\"There is no limit to the extent of the six opulences of the Supreme Personality of Godhead. Here and in many other places there is repetition, but according to the scriptures, repetition of the glories of Kṛṣṇa is not a literary weakness. It is said that at a time of bewilderment or wonder or of great ecstasy, statements are repeated over and over. That is not a flaw.\"}]}],\"short_title\":\"Bg. 11.19\",\"medium_title\":\"Bhagavad-gītā As It Is 11.19\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L25\",\"$L26\",\"$L27\"]}]\n"])self.__next_f.push([1,"29:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n2f:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n25:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8 text-base\",\"children\":[\"$\",\"ol\",null,{\"children\":[[\"$\",\"li\",\"/en/library/\",{\"className\":\"inline\",\"children\":[[\"$\",\"$L20\",nu